package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

/** A revision of a claim in its sheet's history: what its figures were worked out from after a
 *  change, recorded on the sheet's today then. */
@Entity
@Table(name = "claim_revision")
public class ClaimRevision {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    /** The sheet's today when the revision was recorded. */
    @Column(name = "recorded_on", nullable = false)
    private LocalDate recordedOn;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    @Column(name = "stated", nullable = false)
    private boolean stated;

    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    @Column(name = "stated_na", nullable = false)
    private boolean statedNa;

    @Column(name = "corrected_date")
    private LocalDate correctedDate;

    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The claim's place in the order claims are added (see Claim#getAdded). */
    @Column(name = "added", nullable = false)
    private long added;

    /** Whether the claim had left the sheet by then (see {@link #gone(LocalDate)}). */
    @Column(name = "gone", nullable = false)
    private boolean gone;

    protected ClaimRevision() {
    }

    /** A revision of the claim as it is now, recorded on the day. */
    public ClaimRevision(Claim claim, LocalDate recordedOn) {
        this.sheetId = claim.getSheetId();
        this.claimId = claim.getId();
        this.recordedOn = recordedOn;
        this.personId = claim.getPersonId();
        this.amount = claim.getAmount();
        this.date = claim.getDate();
        this.status = claim.getStatus();
        this.settledDue = claim.getSettledDue();
        this.stated = claim.isStated();
        this.statedDue = claim.getStatedDue();
        this.statedNa = claim.isStatedNa();
        this.correctedDate = claim.getCorrectedDate();
        this.dueBy = claim.getDueBy();
        this.deferredUntil = claim.getDeferredUntil();
        this.added = claim.getAdded();
    }

    /** The revision recording, on the day, that the claim has left the sheet: as this one has it
     *  otherwise. */
    public ClaimRevision gone(LocalDate recordedOn) {
        ClaimRevision left = new ClaimRevision();
        left.sheetId = sheetId;
        left.claimId = claimId;
        left.recordedOn = recordedOn;
        left.personId = personId;
        left.amount = amount;
        left.date = date;
        left.status = status;
        left.settledDue = settledDue;
        left.stated = stated;
        left.statedDue = statedDue;
        left.statedNa = statedNa;
        left.correctedDate = correctedDate;
        left.dueBy = dueBy;
        left.deferredUntil = deferredUntil;
        left.added = added;
        left.gone = true;
        return left;
    }

    /** Whether the claim had left the sheet by this revision. */
    public boolean isGone() {
        return gone;
    }

    /** Whether the claim is now as this revision has it. */
    public boolean matches(Claim claim) {
        return Objects.equals(personId, claim.getPersonId()) && same(amount, claim.getAmount())
                && Objects.equals(date, claim.getDate()) && status == claim.getStatus()
                && same(settledDue, claim.getSettledDue()) && stated == claim.isStated()
                && same(statedDue, claim.getStatedDue()) && statedNa == claim.isStatedNa()
                && Objects.equals(correctedDate, claim.getCorrectedDate()) && Objects.equals(dueBy, claim.getDueBy())
                && Objects.equals(deferredUntil, claim.getDeferredUntil());
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

-- The sheet's history: after each change that can move its figures, a revision of every claim,
-- person, rate and dated setting the change left different from its last revision (and of the
-- policy date), stamped with the sheet's today then. The sheet as it stood at the end of a day is
-- the last revision of each stamped on or before that day.
CREATE TABLE claim_revision (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id       BIGINT         NOT NULL,
    recorded_on    DATE           NOT NULL,
    person_id      BIGINT         NOT NULL,
    amount         DECIMAL(14, 2) NOT NULL,
    claim_date     DATE           NOT NULL,
    status         VARCHAR(20)    NOT NULL,
    settled_due    DECIMAL(14, 2),
    stated         BOOLEAN        NOT NULL,
    stated_due     DECIMAL(14, 2),
    stated_na      BOOLEAN        NOT NULL,
    corrected_date DATE,
    due_by         DATE           NOT NULL,
    deferred_until DATE
);
CREATE INDEX claim_revision_sheet ON claim_revision (sheet_id, id);

-- A person's grades and holds are kept as text: each grade "from:grade" and each hold "from..to"
-- (a day left blank when there is none), separated by ";".
CREATE TABLE person_revision (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    person_id    BIGINT        NOT NULL,
    recorded_on  DATE          NOT NULL,
    name         VARCHAR(200)  NOT NULL,
    grades       VARCHAR(4000) NOT NULL,
    holds        VARCHAR(4000) NOT NULL,
    retired_from DATE,
    terms        INT
);
CREATE INDEX person_revision_sheet ON person_revision (sheet_id, id);

CREATE TABLE rate_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade       VARCHAR(1)   NOT NULL,
    from_date   DATE,
    recorded_on DATE         NOT NULL,
    pct         DECIMAL(7, 2) NOT NULL,
    to_date     DATE
);
CREATE INDEX rate_revision_sheet ON rate_revision (sheet_id, id);

CREATE TABLE setting_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(50)    NOT NULL,
    from_date   DATE           NOT NULL,
    recorded_on DATE           NOT NULL,
    setting     DECIMAL(14, 2)
);
CREATE INDEX setting_revision_sheet ON setting_revision (sheet_id, id);

CREATE TABLE sheet_revision (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet (id),
    recorded_on DATE         NOT NULL,
    policy_date DATE
);
CREATE INDEX sheet_revision_sheet ON sheet_revision (sheet_id, id);

-- What a sheet holds already is its first revision, stamped with its today.
INSERT INTO claim_revision (sheet_id, claim_id, recorded_on, person_id, amount, claim_date, status, settled_due,
        stated, stated_due, stated_na, corrected_date, due_by, deferred_until)
    SELECT c.sheet_id, c.id, s.today, c.person_id, c.amount, c.claim_date, c.status, c.settled_due, c.stated,
        c.stated_due, c.stated_na, c.corrected_date, c.due_by, c.deferred_until
    FROM claim c JOIN sheet s ON s.id = c.sheet_id ORDER BY c.id;
INSERT INTO person_revision (sheet_id, person_id, recorded_on, name, grades, holds, retired_from, terms)
    SELECT p.sheet_id, p.id, s.today, p.name,
        COALESCE((SELECT LISTAGG(COALESCE(CAST(g.from_date AS VARCHAR), '') || ':' || g.grade, ';')
            WITHIN GROUP (ORDER BY g.from_date NULLS FIRST) FROM person_grade g WHERE g.person_id = p.id), ''),
        COALESCE((SELECT LISTAGG(COALESCE(CAST(h.from_date AS VARCHAR), '') || '..'
            || COALESCE(CAST(h.to_date AS VARCHAR), ''), ';')
            WITHIN GROUP (ORDER BY h.from_date NULLS FIRST) FROM person_hold h WHERE h.person_id = p.id), ''),
-- Each person's opening balance for a period: what pasted opening balances have added to their
-- carried figure for it. A person with no row has 0.00 opening. Unlike the fixed carried figures it
-- stays when the period is reopened.
CREATE TABLE period_person_opening (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    opening   DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The sheet's history keeps them too, as text: "person-id:opening", separated by ";".
ALTER TABLE period_revision ADD COLUMN person_openings VARCHAR(4000) DEFAULT '' NOT NULL;

